def pairs_fill(inp, maxgap, flood=False):
    dots=inp!=inp.flat[0]  # non-bg color
    bg=inp.flat[0]
    g=inp.copy().astype(int)
    h,w=inp.shape
    filled=np.zeros_like(dots)
    for r in range(h):
        cols=np.where(dots[r])[0]
        for a,b in zip(cols,cols[1:]):
            if b-a-1<=maxgap:
                filled[r,a+1:b]=True
    for c in range(w):
        rows=np.where(dots[:,c])[0]
        for a,b in zip(rows,rows[1:]):
            if b-a-1<=maxgap:
                filled[a+1:b,c]=True
    if flood:
        # flood filled region through non-dot cells (4-conn)
        from collections import deque
        vis=np.zeros_like(filled)
        q=deque(map(tuple,np.argwhere(filled)))
        vis[tuple(np.array(q).T)] = True if q else False
        for r,c in q: vis[r,c]=True
        while q:
            r,c=q.popleft()
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and not dots[nr,nc] and not vis[nr,nc]:
                    vis[nr,nc]=True;q.append((nr,nc))
        filled=vis
    pred=inp.copy()
    pred[(~dots)&filled]=3
    return pred

